from pathlib import Path
import shutil, re
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

SCHOOL='开江中学实验学校'; DATE='二〇二六年七月'
RED='9E2A2B'; NAVY='18324A'; GOLD='B28A42'; GRAY='666666'; PALE='F7F9FB'; PRED='F8EEEE'; PGOLD='F7F2E7'
OUT=Path(__file__).parent/'output'; ROOT=OUT/'开江中学实验学校红专学校发展规划首批十份核心文件'

def safe(s): return re.sub(r'[\\/:*?"<>|]','_',s)
def font(run,name='SimSun',size=12,bold=False,color=None):
    run.font.name=name; run._element.rPr.rFonts.set(qn('w:eastAsia'),name); run.font.size=Pt(size); run.bold=bold
    if color: run.font.color.rgb=RGBColor.from_string(color)
def shade(cell,fill):
    pr=cell._tc.get_or_add_tcPr(); sh=pr.find(qn('w:shd'))
    if sh is None: sh=OxmlElement('w:shd'); pr.append(sh)
    sh.set(qn('w:fill'),fill)
def border(cell,color='D8DEE6'):
    pr=cell._tc.get_or_add_tcPr(); b=pr.first_child_found_in('w:tcBorders')
    if b is None: b=OxmlElement('w:tcBorders'); pr.append(b)
    for e in ('top','left','bottom','right','insideH','insideV'):
        x=b.find(qn('w:'+e))
        if x is None: x=OxmlElement('w:'+e); b.append(x)
        x.set(qn('w:val'),'single'); x.set(qn('w:sz'),'6'); x.set(qn('w:color'),color)
def page_no(p):
    p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(); a=OxmlElement('w:fldChar'); a.set(qn('w:fldCharType'),'begin'); i=OxmlElement('w:instrText'); i.set(qn('xml:space'),'preserve'); i.text=' PAGE '; z=OxmlElement('w:fldChar'); z.set(qn('w:fldCharType'),'end'); r._r.extend([a,i,z])
def setup(doc,title):
    s=doc.sections[0]; s.top_margin=Cm(2.2); s.bottom_margin=Cm(2); s.left_margin=Cm(2.4); s.right_margin=Cm(2.2); s.header_distance=Cm(.8); s.footer_distance=Cm(.8)
    n=doc.styles['Normal']; n.font.name='SimSun'; n._element.rPr.rFonts.set(qn('w:eastAsia'),'SimSun'); n.font.size=Pt(12); n.paragraph_format.line_spacing=1.55; n.paragraph_format.space_after=Pt(6); n.paragraph_format.first_line_indent=Cm(.74)
    for sn,sz,c in [('Title',24,RED),('Heading 1',16,RED),('Heading 2',14,NAVY),('Heading 3',12.5,GOLD)]:
        st=doc.styles[sn]; st.font.name='Microsoft YaHei'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Microsoft YaHei'); st.font.size=Pt(sz); st.font.bold=True; st.font.color.rgb=RGBColor.from_string(c); st.paragraph_format.space_before=Pt(10); st.paragraph_format.space_after=Pt(6); st.paragraph_format.keep_with_next=True
    h=s.header.paragraphs[0]; h.alignment=WD_ALIGN_PARAGRAPH.CENTER; font(h.add_run('开江中学实验学校“红专”学校发展规划核心文件'),'Microsoft YaHei',9,color=GRAY); page_no(s.footer.paragraphs[0]); doc.core_properties.title=title; doc.core_properties.author=SCHOOL

def cover(doc,title,subtitle,label='校级审议稿'):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(45); font(p.add_run(SCHOOL),'Microsoft YaHei',16,True,NAVY)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(28); font(p.add_run(title),'Microsoft YaHei',24,True,RED)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(9); font(p.add_run(subtitle),'Microsoft YaHei',14,True,NAVY)
    t=doc.add_table(rows=1,cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; c=t.cell(0,0); shade(c,PGOLD); border(c,GOLD); q=c.paragraphs[0]; q.alignment=WD_ALIGN_PARAGRAPH.CENTER; font(q.add_run(label),'Microsoft YaHei',12,True,GOLD)
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(85); font(p.add_run(SCHOOL+'\n'+DATE),size=12,color=GRAY); doc.add_page_break()
def callout(doc,title,text):
    t=doc.add_table(rows=1,cols=1); t.alignment=WD_TABLE_ALIGNMENT.CENTER; c=t.cell(0,0); shade(c,PRED); border(c,RED); p=c.paragraphs[0]; p.paragraph_format.first_line_indent=Cm(0); font(p.add_run(title+'：'),'Microsoft YaHei',11,True,RED); font(p.add_run(text),size=11,color='333333'); doc.add_paragraph()
def bullets(doc,items):
    for x in items:
        p=doc.add_paragraph(style='List Bullet'); p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.left_indent=Cm(.65); font(p.add_run(x),size=11.5,color='222222')
def numbered(doc,items):
    for x in items:
        p=doc.add_paragraph(style='List Number'); p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.left_indent=Cm(.65); font(p.add_run(x),size=11.5,color='222222')
def table(doc,headers,rows):
    t=doc.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for j,h in enumerate(headers):
        c=t.rows[0].cells[j]; shade(c,NAVY); border(c); p=c.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER; font(p.add_run(h),'Microsoft YaHei',10,True,'FFFFFF')
    for i,row in enumerate(rows):
        cs=t.add_row().cells
        for j,x in enumerate(row):
            cs[j].text=str(x); cs[j].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; border(cs[j]);
            if i%2==0: shade(cs[j],PALE)
            for p in cs[j].paragraphs:
                p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.space_after=Pt(2)
                for r in p.runs: font(r,size=9.5,color='222222')
    doc.add_paragraph()
def sec(doc,h,paras=None,bs=None,nums=None,level=1):
    doc.add_heading(h,level=level)
    for x in paras or []: doc.add_paragraph(x)
    if bs: bullets(doc,bs)
    if nums: numbered(doc,nums)
def end(doc,text='本文件经学校审议后施行，由学校办公室会同相关系统牵头部门负责解释和版本管理。'):
    sec(doc,'附则',[text,'正式发布前，应核定领导分工、部门名称、基线数据、政策文号和涉及教师学生权益的具体条款。未经审议，不得擅自改变“三层八系统”总体架构和核心术语。'])
def save(doc,name): ROOT.mkdir(parents=True,exist_ok=True); doc.save(ROOT/safe(name))

def new(title,subtitle,position):
    d=Document(); setup(d,title); cover(d,title,subtitle); callout(d,'文件定位',position); return d

