table(d,['类别','系统','核心功能'],[['育人运行','红专学生成长系统','学生成长、班级建设、评价激励和重点关爱'],['育人运行','红专课程教学系统','课程、课堂、作业、教研和学习支持'],['育人运行','红专教师发展系统','教师专业、育人、研究、协作和数字能力'],['育人运行','红专家校社协同系统','家庭、学校、社会责任互补和资源共享'],['治理保障','红专治理系统','党建、规划、项目、责任、制度、协同和减负'],['治理保障','红专质量体系','标准、证据、评价、研究、复盘和成果转化'],['治理保障','红专数智系统','平台、人工智能、数据治理、隐私和伦理'],['治理保障','红专保障系统','安全、健康、心理、后勤、经费、设施和应急']])
sec(d,'五、红专育人核心模型',bs=['育人目标：“三红三专”校本育人目标模型。','组织机制：全员、全过程、全方位的三全育人。','育人内容：德智体美劳五育融合。','实施场景：课程课堂域、活动实践域、管理服务域、文化环境域、家校社会域。','方式变革：数字赋能。','成长主线：七年级适应筑基、八年级稳定发展、九年级励志成长。','评价导向：发展性评价。'])
