sec(d,'一、发展基础与主要问题',['学校具有办学历史、城区生源基础和改革愿望，同时面临学生差异加大、重点青少年风险突出、心理支持力量不足、课程教学提质压力、教师梯队不均、家校协同不足、台账偏重和数字规范不足等问题。规划坚持问题解决、基线先行和循序渐进。'])
sec(d,'二、指导思想',['全面贯彻党的教育方针，落实立德树人，主动对接基础教育扩优提质、健康第一、强师兴教、教育数字化和县域优质均衡要求，以红专文化为根基，以“三红三专”为目标，以三层八系统为架构，促进学生、教师和学校共同发展。'])
sec(d,'三、总体定位',bs=['县域义务教育优质均衡的高质量初中。','具有红专育人特色和文化辨识度的现代学校。','以课程课堂提质、教师发展和精准育人为核心的改进型学校。','安全健康、依法治理、数据规范、能够持续学习的学校组织。'])
sec(d,'四、五年目标',['到2030年，基本形成价值稳定、育人清晰、课程优质、教师有力、协同顺畅、治理规范、质量可证、数智适度、安全可靠的红专学校发展体系，形成一批可复制的县域初中实践经验。'])
sec(d,'五、阶段安排'); table(d,['阶段','时间','重点任务'],[['整改筑基','2026—2027','统一架构术语；完成基线；优先解决学生风险、心理安全、评价整合、教学准备和教师减负；启动少数试点'],['系统提质','2028—2029','八系统稳定运行；课程课堂、教师梯队、家校社协同和质量改进形成机制；扩大成熟项目'],['定型总结','2030','评估五年目标；固化有效制度和课程；形成质量报告、成果集和下一周期规划']])
sec(d,'六、三层建设任务',bs=['文化体系：完善文化内核、校史资源、共同语言、空间表达和命名规范。','育人体系：完成三红三专标准、三年成长地图、五域图谱、发展性评价和全员育人责任。','运行体系：八系统职责清楚、年度项目精简、证据反馈有效、资源安全有保障。'])
sec(d,'七、八系统五年重点'); table(d,['系统','五年重点'],[['学生成长','学生标准、成长课程、班级建设、发展性评价、一生一策和心理成长支持'],['课程教学','课程图谱、课堂改进、备课、作业、分层支持、初高中衔接和校本课程群'],['教师发展','四维四级支持型梯队、青蓝工程、班主任发展、团队教研、关怀减负'],['家校社协同','家长学校、沟通规范、重点家庭支持、部门协同和资源库'],['治理','党组织领导、规划项目化、责任矩阵、制度版本、教师参与和形式主义治理'],['质量','核心指标、证据框架、基线监测、复盘、质量报告、课题成果'],['数智','平台治理、AI适度试点、师生数字素养、数据权限、隐私伦理'],['保障','校园安全、心理危机、消防食品交通实验、后勤设施、应急资源']])
sec(d,'八、重点工程',bs=['红专学子“三红三专”培育工程。','红专课程教学提质工程。','红专教师“四维四级”专业发展支持工程。','重点青少年“一生一策”关爱工程。','红专家长学校与家校社协同工程。','学校治理减负与质量改进工程。','数智教育小步试点工程。','安全健康与心理支持补短工程。'])
sec(d,'九、推进和保障',bs=['每学年只确定少数跨系统重点项目。','每个项目明确基线、目标、责任、资源、风险和最少证据。','重大改革先试点、再评估、后推广。','涉及权益、心理、隐私和安全的事项先审核后实施。','每年形成质量报告和规划执行评估。']); end(d,'本规划经学校审议通过后实施，是年度计划、八系统方案、重点项目、课题研究和质量报告的直接上位依据。'); save(d,'04_开江中学实验学校2026—2030年高质量发展规划.docx')

# 05
d=new('开江中学实验学校2026—2030年学校发展核心指标体系','少而关键 · 基线先行 · 发展评价','建立五年核心指标域和关键观察点，不作为面向个人的高频排名考核表。缺少可靠基线的指标，2026年先建立基线，再核定提升值。')
sec(d,'一、指标原则',bs=['聚焦学生发展和学校改进，不追求数量。','定量与定性、结果与过程、平均水平与公平差异结合。','指标用于诊断、支持、复盘和规划调整。','同一数据一次采集、多方使用。','不虚构基线，不预设无法验证的绝对目标。'])
table(d,['指标域','核心回答'],[['A 学生发展','学生在品德、学业、身心、能力、特长和责任方面是否真实成长'],['B 课程教学','课程是否完整，课堂、作业、教研和学习支持是否有效'],['C 教师发展','教师专业、育人、协作和职业福祉是否提升'],['D 家校社协同','家庭、学校、社会是否形成有效支持'],['E 治理质量','决策、责任、项目、制度和减负是否有效'],['F 质量改进','学校能否形成证据、复盘并持续改进'],['G 数智发展','数字技术是否适度、安全、有效服务育人'],['H 安全保障','生命安全、身心健康和资源运行是否可靠']])
table(d,['编码','指标','核心观察点','使用提示'],[['A1','学生价值品质','三红目标、规则责任、同伴关系','成长性与代表性事实'],['A2','学业发展','达标、增值、习惯、薄弱学科改善','不唯平均分和名次'],['A3','身心健康','体质、睡眠、心理体验、归属和求助','保护隐私'],['A4','能力与特长','劳动、艺术、体育、科创、表达合作','关注机会公平'],['A5','重点学生支持','建档、措施、转介、返校、稳定','看效果不看材料厚度'],['B1','课程实施','开齐开足、课程图谱、校本课程、五育融合','抽样核验'],['B2','课堂学习','目标、参与、反馈、迁移和体验','多源证据'],['B3','作业与支持','总量、分层、反馈、辅导','负担与效益'],['C1','教师专业成长','师德、教学、育人、研究、数字和协作','分阶段发展'],['C2','教师梯队','四级培养覆盖和带动作用','不等同行政等级'],['C3','教师福祉','负担、支持感、参与感、认同','匿名调查'],['D1','家校沟通','及时、尊重、问题解决和体验','不唯到会率'],['D2','外部协同','重点个案、实践和专业资源效果','看实际支持'],['E1','责任协同','一事一主责、重复事项、解决效率','项目抽样'],['E2','减负治理','会议、表格、台账和教师时间','年度清理'],['F1','证据与复盘','基线、项目复盘、改进落实','结果用于调整'],['G1','数智有效性','工具适配、教学价值、公平和素养','不以频次评价'],['G2','数据安全','权限、隐私、账号、准入和事件处置','底线指标'],['H1','安全健康','隐患、应急、心理支持和事故事件','过程底线并重'],['H2','资源保障','人员、经费、场地、设备和维护','投入与效益']])
sec(d,'二、年度目标设定',nums=['2026年完成基线核定和数据责任确认。','2027年根据基线确定合理提升值。','2028—2029年观察系统稳定性和公平差异改善。','2030年开展五年综合评价。'])
sec(d,'三、结果使用边界',bs=['用于规划、资源配置、项目调整和专业支持。','不直接替代教师考核、职称评审和学生升学评价。','敏感数据只在授权范围使用。','指标异常先诊断原因，不简单追责。']); end(d); save(d,'05_2026—2030年学校发展核心指标体系.docx')

# 06
d=new('开江中学实验学校学校发展质量证据框架','一次采集 · 多源互证 · 结果促改','明确核心指标靠什么证据判断、谁提供、何时采集以及如何使用，防止用材料数量替代真实成效。')
sec(d,'一、证据原则',bs=['相关性：直接支持所判断的问题。','可靠性：来源清楚、口径稳定、能够核验。','多元性：数据、观察、作品、访谈和案例互证。','适度性：只收集决策需要的证据。','发展性：用于解释变化和改进。','安全性：保护学生、教师和家庭隐私。'])
table(d,['证据类型','示例','适用范围'],[['行政业务数据','学籍、考勤、课程表、体质、成绩、隐患整改','基础事实与趋势'],['过程观察','课堂、班级、活动、设施巡查','实施质量'],['代表性成果','学生作品、课程成果、课例案例','能力和质量表现'],['体验反馈','学生、教师、家长调查访谈','归属、负担、支持和体验'],['个案证据','一生一策、心理转介、学习支持、家校协同','复杂问题变化'],['研究与复盘','基线、中期评估、质量报告、课题成果','解释原因和改进']])
sec(d,'二、责任规则',bs=['业务系统负责原始事实和业务数据。','质量体系负责口径、抽样、综合分析和复盘。','数智系统负责标准、权限、存储和安全。','治理系统负责减少重复采集和处理争议。','敏感个案实行最小知情和分级授权。'])
table(d,['领域','主要证据','频次'],[['学生发展','成长观察、学业增值、体质心理、作品、访谈、重点个案','学期与学年'],['课程教学','课程计划、课堂抽样、作业样本、学情、教师复盘','月度抽样、学期复盘'],['教师发展','发展目标、课例成果、团队贡献、教师体验','学期与学年'],['家校社','沟通抽样、家长反馈、协同个案、资源使用','学期'],['治理','任务书、责任矩阵、会议表格清理、问题解决','季度与学期'],['质量','基线、监测、复盘、改进清单和年度报告','学期与年度'],['数智','工具准入、使用场景、效果、权限和安全事件','按项目、年度'],['保障','隐患、整改、演练、设施维护、心理转介','常态、月度、年度']])
sec(d,'三、最小化清单',nums=['每个项目设置3—5项核心证据。','一张表能解决的不拆成多张表。','平台和业务记录能证明的，不重复上传。','照片只作辅助，不作唯一证据。','材料抽样优于全量报送。'])
sec(d,'四、分析与保密',bs=['区分事实、判断和建议，不夸大因果。','学期复盘聚焦项目去留，年度报告聚焦整体改进。','高风险问题及时预警。','心理、涉案、家庭困难和教师健康信息严格授权。','公开报告使用汇总数据和匿名案例。']); end(d); save(d,'06_学校发展质量证据框架.docx')

# 07
d=new('开江中学实验学校学校发展与课题研究一体化实施方案','问题即课题 · 项目即研究 · 成果回到实践','把学校重点问题、年度项目、校本研究和成果转化贯通起来，避免课题与真实工作两张皮。')
sec(d,'一、总体目标',['建立“问题诊断—项目设计—行动研究—证据分析—复盘改进—成果转化”机制，使课题直接服务学生成长、课程教学、教师发展和治理。'])
sec(d,'二、基本原则',bs=['真实问题优先，不为申报虚构问题。','小切口、可行动、可观察。','项目实施与研究同步设计，不额外制造材料。','教师参与以专业成长和解决问题为导向。','成果首先回到课程、制度和工具。'])
