sec(d,'三、选题范围',bs=['三红三专学生标准和评价。','一生一策、心理健康和欺凌治理。','课程图谱、课堂、作业和分层支持。','教师四维四级、班主任发展和减负。','家校社协同和困难家庭支持。','治理、质量证据、数字赋能和安全保障。'])
sec(d,'四、流程',nums=['基线诊断。','方案设计。','小范围试行。','中期分析。','持续改进。','总结转化。','成果评审。'])
sec(d,'五、组织职责',bs=['质量体系统筹研究规划、方法支持、证据审核和成果认定。','治理系统将重点研究纳入年度项目并协调资源。','业务系统提出问题、组织行动并负责实践质量。','教研组、年级和教师作为研究主体。','涉及心理、个案、数据和权益的研究完成伦理与隐私审核。'])
sec(d,'六、成果与减负',bs=['成果包括制度流程、课程课例、学生案例、评价工具、研究报告和质量报告。','项目记录与课题材料合并。','不要求人人申报课题、人人发表论文。','不以课题数量和材料厚度评价教师。','优先提供时间、方法、数据和编辑支持。']); end(d); save(d,'07_学校发展与课题研究一体化实施方案.docx')

# 08
d=new('开江中学实验学校红专文化建设纲要','文化定向 · 价值入心 · 行为落地','明确价值内核、主要内容、实施方式和审核边界。文化不是装饰和活动集合，而是共同作出教育判断的价值操作系统。')
sec(d,'一、文化定位',['红专文化体系以学校历史文脉、党的教育方针、立德树人要求和现代学校发展需要为基础，形成师生共同理解、共同遵循、共同创造的学校文化。'])
sec(d,'二、建设目标',bs=['形成稳定、准确、可理解的办学理念和价值表达。','建立真实、可核验、可育人的校史资源。','使文化进入课程、制度、评价、关系和空间。','形成尊重学生、支持教师、务实协作、追求卓越的组织文化。','避免口号化、标签化和过度视觉化。'])
