sec(d,'三、行为准则',bs=['对学生：相信成长，尊重差异，教育优先于标签和惩罚。','对教师：尊重专业，提供支持，减少无效负担。','对课程：坚持国家课程主体地位，追求真实学习。','对治理：依法、公开、协商、负责。','对技术：育人为本、审慎使用、保护隐私。','对安全：生命至上、预防为主、专业支持。'])
sec(d,'四、重点任务',bs=['修订红专文化核心释义。','建立校史资源征集、审核、保存和使用机制。','开发校史、红色乡土和学校精神课程资源。','形成项目命名、宣传发布和视觉规范。','建设班级文化、教师文化、家长文化和服务文化。','通过制度审查检验文化落地。'])
sec(d,'五、实施评价',bs=['党委统一领导，办公室统筹标准和表达。','课程、学生、教师系统分别推进课程化、实践化和组织文化。','治理与质量负责制度一致性和复盘。','评价关注师生理解、制度一致、归属体验和真实育人价值。']); end(d); save(d,'08_红专文化建设纲要.docx')

